#include <stdio.h>
#include <ctype.h>

int main(void) {
    int c;
    int letters = 0, digits = 0, spaces = 0, others = 0;
    while ((c = getchar()) != EOF) {
        if (isalpha(c)) {
            letters++;
        } else if (isdigit(c)) {
            digits++;
        } else if (isspace(c)) {
            spaces++;
        } else {
            others++;
        }
    }
    printf("%d %d %d %d\n", letters, digits, spaces, others);
    return 0;
}

