#include <stdio.h>
#include <ctype.h>

int main(void) {
    int c;
    long long sum = 0;
    while ((c = getchar()) != EOF) {
        if (isdigit(c)) {
            sum += c - '0';
        }
    }
    printf("%lld\n", sum);
    return 0;
}

