#include <stdio.h>
#include <ctype.h>

int main(void) {
    int k;
    scanf("%d", &k);
    getchar();
    k %= 26;
    int c;
    while ((c = getchar()) != EOF) {
        if (islower(c)) {
            c = (c - 'a' + k) % 26 + 'a';
        } else if (isupper(c)) {
            c = (c - 'A' + k) % 26 + 'A';
        }
        putchar(c);
    }
    return 0;
}

